<div class="flex items-end justify-between mb-8"><div><div class="text-sm text-gray-500">Newsroom intake</div><h1 class="display text-4xl font-bold">News discovery</h1></div><button id="fetch" class="bg-[#b8e64b] text-[#101513] rounded-lg px-4 py-3 font-semibold">Fetch news</button></div><form class="bg-white rounded-2xl shadow-sm p-5 mb-5 grid md:grid-cols-4 gap-3"><input name="q" value="<?=e($_GET['q']??'')?>" placeholder="Search…" class="rounded-lg border border-gray-200 px-3 py-2"><select name="source" class="rounded-lg border border-gray-200 px-3 py-2"><option value="">All sources</option><?php foreach($sources as $s): ?><option value="<?=$s['id']?>" <?=($_GET['source']??'')==$s['id']?'selected':''?>><?=e($s['name'])?></option><?php endforeach; ?></select><select name="category" class="rounded-lg border border-gray-200 px-3 py-2"><option value="">All categories</option><?php foreach($categories as $c): ?><option value="<?=$c['id']?>" <?=($_GET['category']??'')==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach; ?></select><button class="rounded-lg bg-[#101513] text-white font-semibold">Filter</button></form><div id="notice" class="hidden mb-5 rounded-xl bg-[#e9f7c7] px-4 py-3 text-sm"></div><div class="bg-white rounded-2xl shadow-sm overflow-hidden"><div class="divide-y"><?php foreach($items as $item): ?><article class="p-5 flex flex-col md:flex-row md:items-center justify-between gap-4"><div><div class="font-semibold"><?=e($item['title'])?></div><div class="text-xs text-gray-500 mt-2"><?=e($item['source_name'])?> · <?=e($item['category_name']??'Uncategorized')?> · <?=e($item['published_at']??'')?></div></div><div class="flex gap-3 text-sm"><a target="_blank" rel="noopener" href="<?=e($item['url'])?>" class="underline">View</a><a href="/admin/ai-studio?news_id=<?=$item['id']?>" class="font-semibold text-[#688d1b]">Generate</a></div></article><?php endforeach; ?><?php if(!$items): ?><div class="p-12 text-center text-gray-500">No matching news items.</div><?php endif; ?></div></div><script>const csrf='<?=e(csrf_token())?>';document.getElementById('fetch').onclick=async()=>{const b=document.getElementById('fetch');b.disabled=true;b.textContent='Fetching…';const r=await fetch('/api/fetch-news',{method:'POST',body:new URLSearchParams({csrf})});const d=await r.json();document.getElementById('notice').textContent=`Imported ${d.imported} new stories${d.errors?.length?' (some sources failed)':''}.`;document.getElementById('notice').classList.remove('hidden');b.disabled=false;b.textContent='Fetch news';};</script>
